-- =============================================================================
-- Studuel — Migration 280 : SES 2de — LE PROGRAMME COMPLET (23 fiches)
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main.
--    Source : scripts/contenu/*.mjs
--    Regénérer : node scripts/seed-contenu.mjs --num 280 --modules ses-2de
--
-- CONSTAT : la Seconde n'avait que QUATRE chapitres de SES, hérités du
-- premier jeu de données de l'app, avec deux leçons génériques chacun. Le
-- programme officiel en compte SIX — les trois regards des sciences sociales, la
-- production et sa mesure, le marché, la socialisation, la vie politique, et les
-- relations entre diplôme, emploi et salaire — soit 23 fiches. Un élève de 2de
-- qui révisait le PIB, la croissance et ses limites écologiques, la Ve
-- République, les modes de scrutin, le capital humain ou les inégalités de
-- salaire ne trouvait RIEN. Cette migration installe les 23 fiches, rangées sous
-- leurs 6 chapitres, et retire les 4 fiches génériques que ce découpage recouvre.
--
-- Cette migration apporte : 23 chapitres, 23 leçons,
-- 23 quiz et 184 questions, sur 1 matière.
--
-- CHOIX ASSUMÉS :
--  · tous les quiz sont `is_free = true`. Aucun compte ne peut aujourd’hui
--    passer `tier1` (aucun paiement n’existe), donc un quiz payant serait un
--    quiz INVISIBLE pour 100 % des élèves — le contraire du but ;
--  · chaque cours porte des sections `##`, ce qui rend sa carte mentale
--    dérivable (cf. lib/mind-map-auto) : aucune tuile ne promet dans le vide.
--
-- Idempotent : les UUID sont dérivés du contenu (SHA-1), donc stables ; les
-- INSERT sont tous gardés par ON CONFLICT DO NOTHING. Rejouable sans risque.
--
-- PRÉREQUIS : 002, 008, 191, 193 exécutées (les matières doivent exister).
-- À exécuter dans : Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

-- 0. Ménage ----------------------------------------------------------------
-- [ses] La colonne chapters.theme (migration 234) conditionne tout ce qui suit :
-- [ses] ce module range ses 23 fiches sous 6 chapitres, et l'INSERT écrit la colonne.
-- [ses] Elle est REPRISE ici en ADD COLUMN IF NOT EXISTS parce qu'on ne peut pas
-- [ses] garantir que la 234 soit passée en production — sans cette reprise, la migration
-- [ses] échouerait sur "column chapters.theme does not exist", les 4 anciens chapitres
-- [ses] déjà supprimés et les 23 neufs pas encore posés : une matière vide.
-- [ses] Le GRANT n'est pas décoratif : la migration 182 a révoqué le SELECT de table sur
-- [ses] chapters (pour cacher mind_map) et ne l'a rendu que colonne par colonne. Une
-- [ses] colonne ajoutée après elle n'hérite d'aucun droit — sans lui, l'app lirait
-- [ses] "permission denied" au lieu du chapitre.
ALTER TABLE public.chapters ADD COLUMN IF NOT EXISTS theme TEXT;
GRANT SELECT (theme) ON public.chapters TO anon;
GRANT SELECT (theme) ON public.chapters TO authenticated;

-- [ses] Les 4 chapitres hérités partent. Trois d'entre eux sont des CHAPITRES du
-- [ses] programme reformulés ("Comment raisonnent les économistes ?", "Comment se
-- [ses] forment les prix ?", "La socialisation") : les garder en base ferait deux objets
-- [ses] du même nom à deux places différentes, un en-tête de section et une ligne dans
-- [ses] la liste. Le quatrième ("La production") est une fiche de synthèse que les six
-- [ses] fiches du chapitre 2 recouvrent entièrement.
-- [ses] L'ordre compte : la file "À revoir" d'abord (review_items.item_id n'a PAS de clé
-- [ses] étrangère), puis les quiz (quizzes.lesson_id est ON DELETE SET NULL : ils
-- [ses] survivraient orphelins à leur chapitre, mais toujours tirables par le moteur de
-- [ses] questions), puis les chapitres, dont les leçons partent en cascade.
-- [ses] Les trois DELETE sont bornés aux QUATRE TITRES EXACTS et au seul niveau 2de.
-- [ses] Sans cette borne, un rejeu après coup effacerait les quiz des 23 fiches neuves —
-- [ses] le ménage tourne avant les insertions à CHAQUE passage.
DELETE FROM public.review_items ri
 USING public.quiz_questions qq, public.quizzes qz, public.lessons l,
       public.chapters c, public.subjects s
 WHERE ri.item_kind = 'question'
   AND ri.item_id = qq.id
   AND qq.quiz_id = qz.id
   AND qz.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'ses'
   AND c.level = '2de'
   AND c.title IN ('Comment raisonnent les économistes ?',
                   'La production',
                   'Comment se forment les prix ?',
                   'La socialisation');

DELETE FROM public.quizzes q
 USING public.lessons l, public.chapters c, public.subjects s
 WHERE q.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'ses'
   AND c.level = '2de'
   AND c.title IN ('Comment raisonnent les économistes ?',
                   'La production',
                   'Comment se forment les prix ?',
                   'La socialisation');

DELETE FROM public.chapters c
 USING public.subjects s
 WHERE c.subject_id = s.id
   AND s.slug = 'ses'
   AND c.level = '2de'
   AND c.title IN ('Comment raisonnent les économistes ?',
                   'La production',
                   'Comment se forment les prix ?',
                   'La socialisation');

