    ('e0d3dc90-2333-5473-8c92-55181dee264e'::uuid, 'Quiz — Pourquoi le chômage frappe d’abord les moins diplômés', 'SES', '2de', 'Le manque de qualifications : une des causes du chômage', '6191f883-0b66-50f3-8701-b35ca4c594c1'::uuid),
    ('53f408e3-7afd-5bdc-a7a2-600799206b46'::uuid, 'Quiz — Ce qui explique un bulletin de paie', 'SES', '2de', 'L’influence du diplôme et de l’expérience sur le niveau de salaire', '760a143a-6ec6-5c09-8452-7a3383060974'::uuid),
    ('3f004ee3-f77e-50e5-8b1a-313eddff8f1e'::uuid, 'Quiz — À diplôme égal, des carrières inégales', 'SES', '2de', 'L’influence du genre et de l’origine sociale sur les trajectoires professionnelles', 'f183b7fb-c6fa-5fe9-ab65-73c77fe8d5b2'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
