ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('0e32d7bf-5895-50d5-a73a-6ca03a81a891'::uuid, '37ed674c-0b6e-5d0e-b0f0-dbee773cedcc'::uuid, 'Qu’est-ce que la rareté en économie ?', 'mcq', '["Le fait que les ressources soient limitées face à des besoins illimités","La cherté d’un produit de luxe","La faiblesse de la production agricole","L’absence de concurrence"]'::jsonb, 0, 'C’est le point de départ de toute la discipline.', 1),
    ('613b2ac1-1255-5920-9d35-9e087e160d3a'::uuid, '37ed674c-0b6e-5d0e-b0f0-dbee773cedcc'::uuid, 'Qu’est-ce que le coût d’opportunité ?', 'mcq', '["Ce à quoi on renonce en faisant un choix","Le prix payé pour un bien","Le coût de production d’une entreprise","Une taxe sur les échanges"]'::jsonb, 0, 'Choisir, c’est toujours renoncer à autre chose.', 2),
    ('95892efb-6f9e-53c7-92fa-e06ecad34daf'::uuid, '37ed674c-0b6e-5d0e-b0f0-dbee773cedcc'::uuid, 'Quels agents fournissent du travail et consomment ?', 'mcq', '["Les ménages","Les entreprises","Les administrations publiques","Les banques"]'::jsonb, 0, 'Ils reçoivent des revenus et les dépensent.', 3),
    ('e990086a-52cb-5280-b896-eca36bc55df7'::uuid, '37ed674c-0b6e-5d0e-b0f0-dbee773cedcc'::uuid, 'Dans le circuit économique, les flux monétaires vont dans quel sens ?', 'mcq', '["En sens inverse des flux réels","Dans le même sens que les flux réels","Toujours vers les ménages","Uniquement vers l’État"]'::jsonb, 0, 'À un bien qui circule correspond un paiement en retour.', 4),
    ('c9c3ab9b-9a36-5021-8695-34875779b8b8'::uuid, '37ed674c-0b6e-5d0e-b0f0-dbee773cedcc'::uuid, 'Quelles sont les trois grandes questions de l’économie ?', 'mcq', '["Que produire, comment produire, pour qui produire","Combien vendre, à qui, à quel prix","Épargner, investir, consommer","Produire, échanger, taxer"]'::jsonb, 0, 'Les sociétés y répondent par le marché, l’État, ou les deux.', 5),
    ('149a3389-c8d4-5117-949b-48f9bafaf44c'::uuid, '37ed674c-0b6e-5d0e-b0f0-dbee773cedcc'::uuid, 'Une économie mixte associe marché et intervention publique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Toutes les économies réelles sont mixtes, à des degrés différents.', 6),
    ('eb3d7285-efde-5721-a2f1-7e86e6c8ac3b'::uuid, '37ed674c-0b6e-5d0e-b0f0-dbee773cedcc'::uuid, 'Qu’est-ce qu’un modèle économique ?', 'mcq', '["Une représentation simplifiée de la réalité, fondée sur des hypothèses","Une entreprise qui réussit","Un plan de production","Une prévision certaine"]'::jsonb, 0, 'Il se juge à sa capacité à expliquer les faits observés.', 7),
    ('cf7600ae-143c-530e-950b-5d306261e3e5'::uuid, '37ed674c-0b6e-5d0e-b0f0-dbee773cedcc'::uuid, 'Pourquoi l’économiste peut-il rarement faire des expériences ?', 'mcq', '["Parce qu’il étudie des sociétés entières, qu’on ne peut pas mettre en laboratoire","Parce que les données n’existent pas","Parce que c’est interdit par la loi","Parce que les modèles suffisent"]'::jsonb, 0, 'Il compare donc des pays, des périodes et des situations.', 8),
    ('5cb4914e-cf91-51cb-9179-c1116a26fa3c'::uuid, '2bd3627e-578e-59ca-b82b-751e2a45fa69'::uuid, 'Comment Durkheim définit-il un fait social ?', 'mcq', '["Une manière d’agir extérieure à l’individu et qui exerce une contrainte","Une opinion partagée par la majorité","Un événement historique marquant","Une décision politique"]'::jsonb, 0, 'Le fait social se reconnaît à sa régularité et à sa contrainte.', 1),
    ('9434358a-2f0b-5817-81b4-7fc113c5bcd2'::uuid, '2bd3627e-578e-59ca-b82b-751e2a45fa69'::uuid, 'Quelle étude de Durkheim montre qu’un acte intime est un fait social ?', 'mcq', '["Son étude sur le suicide","Son étude sur le travail industriel","Son étude sur la ville","Son étude sur les partis politiques"]'::jsonb, 0, 'Les taux varient régulièrement selon la religion ou le statut familial.', 2),
    ('1dda0c95-8348-59c6-8102-28a7403b6e8b'::uuid, '2bd3627e-578e-59ca-b82b-751e2a45fa69'::uuid, 'Que privilégie Max Weber dans l’analyse sociologique ?', 'mcq', '["Le sens que les individus donnent à leur action","La contrainte du groupe","Les statistiques nationales","Les institutions politiques"]'::jsonb, 0, 'C’est la sociologie compréhensive.', 3),
    ('1f570d80-55e2-5a5c-8990-38b613003720'::uuid, '2bd3627e-578e-59ca-b82b-751e2a45fa69'::uuid, 'Qu’est-ce que l’individualisme méthodologique ?', 'mcq', '["Expliquer les faits sociaux par l’agrégation des actions individuelles","Étudier les individus isolés","Refuser toute enquête statistique","Privilégier le rôle de l’État"]'::jsonb, 0, 'Il s’oppose au holisme, qui explique par le tout social.', 4),
    ('2ff43f60-bdf3-5887-9934-fb26a67d6adb'::uuid, '2bd3627e-578e-59ca-b82b-751e2a45fa69'::uuid, 'Qu’appelle-t-on rompre avec les prénotions ?', 'mcq', '["Se défaire des idées reçues avant d’analyser","Refuser les entretiens","Ignorer les statistiques","Changer de sujet d’enquête"]'::jsonb, 0, 'Le sens commun n’est pas une explication.', 5),
    ('5f103c2b-260f-575d-bc2d-83355e2c41c9'::uuid, '2bd3627e-578e-59ca-b82b-751e2a45fa69'::uuid, 'Un entretien approfondi relève d’une méthode qualitative.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il cherche à comprendre des logiques, pas à mesurer une fréquence.', 6),
    ('ff2e4d57-0ee6-50c1-8a50-f79b07284bb8'::uuid, '2bd3627e-578e-59ca-b82b-751e2a45fa69'::uuid, 'Quel organisme public produit l’essentiel des statistiques sociales en France ?', 'mcq', '["L’Insee","La Banque de France","Le Conseil constitutionnel","L’Ademe"]'::jsonb, 0, 'Recensement, enquêtes emploi, revenus, conditions de vie.', 7),
    ('4eba3084-8228-5ab2-95f1-e689cdc8f0fd'::uuid, '2bd3627e-578e-59ca-b82b-751e2a45fa69'::uuid, 'Une corrélation entre deux variables prouve-t-elle une causalité ?', 'mcq', '["Non, il faut identifier le mécanisme qui les relie","Oui, toujours","Oui, si elle est forte","Non, une corrélation est une erreur"]'::jsonb, 0, 'Deux variables peuvent varier ensemble sans que l’une cause l’autre.', 8),
    ('1d4766e9-5f17-5a17-8ab0-298c4619f03d'::uuid, '7751a1cb-f444-5fcd-9e7e-bf8289cb637a'::uuid, 'Comment Weber définit-il l’État ?', 'mcq', '["La communauté qui détient le monopole de la violence physique légitime sur un territoire","L’ensemble des fonctionnaires","Le gouvernement en exercice","La nation"]'::jsonb, 0, 'Territoire, population, administration et souveraineté.', 1),
    ('57115e51-4de2-5012-bc2a-0cdc705a5728'::uuid, '7751a1cb-f444-5fcd-9e7e-bf8289cb637a'::uuid, 'Quels sont les trois types de domination légitime selon Weber ?', 'mcq', '["Traditionnelle, charismatique et légale-rationnelle","Directe, indirecte et déléguée","Locale, nationale et internationale","Militaire, religieuse et économique"]'::jsonb, 0, 'La forme légale-rationnelle domine dans les États modernes.', 2),
    ('5074c6d9-4565-56e7-80a8-c59ff7d2561d'::uuid, '7751a1cb-f444-5fcd-9e7e-bf8289cb637a'::uuid, 'Sur quoi repose la domination légale-rationnelle ?', 'mcq', '["Sur la règle écrite et la compétence","Sur la coutume","Sur le charisme du chef","Sur la force armée"]'::jsonb, 0, 'On obéit à la fonction, pas à la personne.', 3),
    ('9126bac8-0754-59d6-9714-8a1170d78527'::uuid, '7751a1cb-f444-5fcd-9e7e-bf8289cb637a'::uuid, 'Qu’étudie la sociologie électorale ?', 'mcq', '["Les déterminants sociaux du vote","Le droit constitutionnel","Le financement des partis","Les relations internationales"]'::jsonb, 0, 'Âge, diplôme, profession, territoire, religion.', 4),
    ('6e9aed28-a197-5e82-972c-353a717c2e53'::uuid, '7751a1cb-f444-5fcd-9e7e-bf8289cb637a'::uuid, 'Un sondage est-il une prédiction du résultat d’une élection ?', 'mcq', '["Non, c’est une estimation assortie d’une marge d’erreur","Oui, s’il est bien fait","Oui, à la veille du scrutin","Non, c’est un simple sondage d’opinion sans valeur"]'::jsonb, 0, 'Il photographie un moment, il ne prédit pas.', 5),
    ('c42a39a1-3767-54f9-8038-264e3daa8380'::uuid, '7751a1cb-f444-5fcd-9e7e-bf8289cb637a'::uuid, 'Le pouvoir se définit comme la capacité d’obtenir d’autrui un comportement qu’il n’aurait pas eu spontanément.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Cette définition vaut au-delà du seul champ politique.', 6),
    ('05af70c1-0505-5597-8238-214bf8e28d68'::uuid, '7751a1cb-f444-5fcd-9e7e-bf8289cb637a'::uuid, 'Quelles méthodes le politiste utilise-t-il ?', 'mcq', '["Des méthodes quantitatives et qualitatives, comme le sociologue","Uniquement le droit constitutionnel","Uniquement les sondages","Uniquement les archives"]'::jsonb, 0, 'Résultats électoraux, entretiens, observation de campagnes.', 7),
    ('45cf3fc2-a33a-5e40-9926-11725fadedc1'::uuid, '7751a1cb-f444-5fcd-9e7e-bf8289cb637a'::uuid, 'L’abstention est-elle un objet d’étude de la science politique ?', 'mcq', '["Oui, c’est un comportement politique à part entière","Non, c’est une absence de comportement","Non, elle n’est pas mesurable","Oui, mais seulement en période de crise"]'::jsonb, 0, 'Elle varie fortement selon l’âge, le diplôme et le type d’élection.', 8),
    ('7757610e-1c6b-5fc4-9ef8-0b097959c8e7'::uuid, '23137b22-8966-5d41-ac1f-b71f3b202e4b'::uuid, 'Quel est le but principal d’une entreprise privée ?', 'mcq', '["Réaliser un profit en vendant sa production","Fournir un service gratuit","Redistribuer les revenus","Employer le plus de personnes possible"]'::jsonb, 0, 'Elle produit des biens et services marchands.', 1),
    ('9a1f50d4-ad79-53b1-a9ba-6e19c8508697'::uuid, '23137b22-8966-5d41-ac1f-b71f3b202e4b'::uuid, 'Qu’est-ce qu’un service non marchand ?', 'mcq', '["Un service fourni gratuitement ou à un prix inférieur à la moitié de son coût","Un service vendu à perte","Un service rendu par une association uniquement","Un service exporté"]'::jsonb, 0, 'École, justice, police : financés par l’impôt.', 2),
    ('72229aef-c8e0-50b4-8eba-2d5e085b29f6'::uuid, '23137b22-8966-5d41-ac1f-b71f3b202e4b'::uuid, 'La production non marchande est-elle comptée dans le PIB ?', 'mcq', '["Oui, évaluée à son coût de production","Non, elle n’a pas de prix","Oui, à sa valeur de marché","Non, sauf pour la santé"]'::jsonb, 0, 'On l’évalue par ce qu’elle coûte, faute de prix de marché.', 3),
    ('4664a1fb-9078-53f4-b0b4-5b80197d22aa'::uuid, '23137b22-8966-5d41-ac1f-b71f3b202e4b'::uuid, 'Quel secteur regroupe les services ?', 'mcq', '["Le secteur tertiaire","Le secteur primaire","Le secteur secondaire","Le secteur quaternaire"]'::jsonb, 0, 'Il représente aujourd’hui l’essentiel de l’emploi en France.', 4),
    ('d71693b0-8f86-525e-8628-5670794f550f'::uuid, '23137b22-8966-5d41-ac1f-b71f3b202e4b'::uuid, 'Quelle catégorie d’entreprises est la plus nombreuse en France ?', 'mcq', '["Les microentreprises","Les grandes entreprises","Les entreprises de taille intermédiaire","Les coopératives"]'::jsonb, 0, 'Les grandes entreprises concentrent en revanche l’essentiel du chiffre d’affaires.', 5),
    ('8ea03944-38d1-55df-861e-f2362f943af1'::uuid, '23137b22-8966-5d41-ac1f-b71f3b202e4b'::uuid, 'Dans une coopérative, chaque associé dispose d’une voix quelle que soit sa part de capital.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une personne, une voix : c’est le principe coopératif.', 6),
    ('360ca308-1afa-54d6-89e5-f06487536175'::uuid, '23137b22-8966-5d41-ac1f-b71f3b202e4b'::uuid, 'Que regroupe l’économie sociale et solidaire ?', 'mcq', '["Coopératives, mutuelles, associations et fondations","Les seules entreprises publiques","Les entreprises exportatrices","Les administrations de l’État"]'::jsonb, 0, 'Environ un salarié privé sur dix en France.', 7),
    ('b641eb11-7a30-5f4c-a692-bcc2c7bca5e9'::uuid, '23137b22-8966-5d41-ac1f-b71f3b202e4b'::uuid, 'Qu’est-ce que produire, en économie ?', 'mcq', '["Combiner des ressources pour créer des biens ou des services","Fabriquer des objets matériels","Vendre des marchandises","Employer des salariés"]'::jsonb, 0, 'Les services sont une production au même titre que les biens.', 8),
    ('7c9bf495-2fff-54df-a717-c4397e5aa55a'::uuid, '69d2031c-fec2-5a50-b4ba-7ced32c7766c'::uuid, 'Quels sont les deux principaux facteurs de production ?', 'mcq', '["Le travail et le capital","Le capital et la monnaie","Le travail et la terre uniquement","Le profit et le salaire"]'::jsonb, 0, 'Auxquels s’ajoutent des ressources naturelles.', 1),
    ('09203f02-8e04-56c0-a278-01e12a0cefb4'::uuid, '69d2031c-fec2-5a50-b4ba-7ced32c7766c'::uuid, 'Qu’est-ce que le capital fixe ?', 'mcq', '["Les biens durables utilisés plus d’un an dans la production","Les matières premières consommées","L’argent en caisse","Les stocks de produits finis"]'::jsonb, 0, 'Machines, bâtiments, logiciels : ils s’usent et s’amortissent.', 2),
    ('2e0ba337-b62f-5019-98b5-a8aab41ec0f0'::uuid, '69d2031c-fec2-5a50-b4ba-7ced32c7766c'::uuid, 'Qu’est-ce que le capital humain ?', 'mcq', '["L’ensemble des savoirs et compétences qui rendent le travail plus productif","Le nombre de salariés d’une entreprise","La masse salariale","Le capital détenu par les ménages"]'::jsonb, 0, 'Formation, expérience et santé en font partie.', 3),
    ('d1c6d257-5bdc-500e-abd0-c320754f259d'::uuid, '69d2031c-fec2-5a50-b4ba-7ced32c7766c'::uuid, 'Comment mesure-t-on la productivité du travail ?', 'mcq', '["En rapportant la production à la quantité de travail utilisée","En divisant le profit par le capital","En comptant les salariés","En mesurant le chiffre d’affaires"]'::jsonb, 0, 'Par tête ou, plus finement, par heure travaillée.', 4),
    ('08e708b2-babd-5326-921a-43ffca1ce21e'::uuid, '69d2031c-fec2-5a50-b4ba-7ced32c7766c'::uuid, 'Que signifie que deux facteurs sont substituables ?', 'mcq', '["On peut remplacer l’un par l’autre pour produire la même chose","Ils doivent être utilisés ensemble","Ils ont le même coût","Ils appartiennent au même propriétaire"]'::jsonb, 0, 'Remplacer du travail par des machines en est l’exemple type.', 5),
    ('2b446d21-3390-55a2-859f-4e72923d973f'::uuid, '69d2031c-fec2-5a50-b4ba-7ced32c7766c'::uuid, 'Les consommations intermédiaires font partie du capital circulant.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles sont détruites ou transformées au cours de la production.', 6),
    ('f787c027-d462-5666-9508-85ee6dec4bf6'::uuid, '69d2031c-fec2-5a50-b4ba-7ced32c7766c'::uuid, 'Qu’est-ce qui explique les gains de productivité ?', 'mcq', '["Le progrès technique, la formation et l’organisation du travail","La hausse des prix","L’augmentation du nombre d’heures travaillées","La croissance de la population"]'::jsonb, 0, 'Produire plus avec autant, ou autant avec moins.', 7),
    ('5c84dfa4-6c86-56e0-8dcc-d4a25d8b4448'::uuid, '69d2031c-fec2-5a50-b4ba-7ced32c7766c'::uuid, 'À quoi peuvent servir les gains de productivité ?', 'mcq', '["À baisser les prix, augmenter les salaires ou les profits, réduire le temps de travail","Uniquement à augmenter les profits","Uniquement à embaucher","À rien, ils sont automatiquement perdus"]'::jsonb, 0, 'Leur partage est un enjeu de conflit social.', 8),
    ('bfb1b1c0-b0ed-5bef-bfe5-e5b84228e116'::uuid, '5d7c87a2-99f8-5f85-8a8c-d4cec76d5307'::uuid, 'Comment calcule-t-on la valeur ajoutée d’une entreprise ?', 'mcq', '["Chiffre d’affaires moins consommations intermédiaires","Chiffre d’affaires moins salaires","Bénéfice moins impôts","Ventes moins investissements"]'::jsonb, 0, 'C’est la richesse réellement créée par l’entreprise.', 1),
    ('7f8fa765-0fdf-56e2-af43-3c093a7917ae'::uuid, '5d7c87a2-99f8-5f85-8a8c-d4cec76d5307'::uuid, 'Que sont les consommations intermédiaires ?', 'mcq', '["Les biens et services achetés à d’autres et détruits ou transformés dans la production","Les machines utilisées plusieurs années","Les salaires versés","Les stocks invendus"]'::jsonb, 0, 'Matières premières, énergie, services achetés.', 2),
    ('0e6fcca7-baf6-550e-a601-6df7f47c1b4b'::uuid, '5d7c87a2-99f8-5f85-8a8c-d4cec76d5307'::uuid, 'Une entreprise réalise 300 000 euros de ventes et consomme 90 000 euros d’intrants. Quelle est sa valeur ajoutée ?', 'mcq', '["210 000 euros","390 000 euros","90 000 euros","300 000 euros"]'::jsonb, 0, 'On retranche du chiffre d’affaires ce qui a été acheté à d’autres.', 3),
    ('936fab39-7c5a-5fa6-836c-0ef86e45b0e8'::uuid, '5d7c87a2-99f8-5f85-8a8c-d4cec76d5307'::uuid, 'Pourquoi ne peut-on pas additionner les chiffres d’affaires pour mesurer la production d’un pays ?', 'mcq', '["On compterait plusieurs fois les mêmes biens","Les chiffres d’affaires ne sont pas connus","Ils incluent les impôts","Ils excluent les services"]'::jsonb, 0, 'La farine serait comptée chez le meunier puis chez le boulanger.', 4),
    ('0478a406-14d8-5af2-bbb1-dbe093e40a5e'::uuid, '5d7c87a2-99f8-5f85-8a8c-d4cec76d5307'::uuid, 'Entre qui se partage la valeur ajoutée ?', 'mcq', '["Salariés, État, prêteurs, propriétaires et l’entreprise elle-même","Uniquement les actionnaires","Uniquement les salariés et l’État","Les clients et les fournisseurs"]'::jsonb, 0, 'Salaires, impôts, intérêts, dividendes, autofinancement.', 5),
    ('40ab5ada-59b8-5d63-bef7-a453aaf4307a'::uuid, '5d7c87a2-99f8-5f85-8a8c-d4cec76d5307'::uuid, 'La TVA est une taxe assise sur la valeur ajoutée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Son nom le dit : taxe sur la valeur ajoutée.', 6),
    ('4f9c58a0-7ec7-5bf1-8bc7-9f265eba4b3c'::uuid, '5d7c87a2-99f8-5f85-8a8c-d4cec76d5307'::uuid, 'Que finance l’autofinancement ?', 'mcq', '["L’investissement de l’entreprise","Les dividendes","Les cotisations sociales","Les consommations intermédiaires"]'::jsonb, 0, 'C’est la part de la valeur ajoutée conservée par l’entreprise.', 7),
    ('a5cbd78d-f90a-5dc6-8cf9-abb9096832b6'::uuid, '5d7c87a2-99f8-5f85-8a8c-d4cec76d5307'::uuid, 'Le partage de la valeur ajoutée est-il un enjeu de conflit ?', 'mcq', '["Oui, entre salaires, profits et investissement","Non, il est fixé par la loi","Non, il est identique dans toutes les entreprises","Oui, mais seulement dans l’industrie"]'::jsonb, 0, 'C’est l’un des principaux objets de la négociation sociale.', 8),
    ('8d061119-9a77-5f85-a5cc-593569d11bb5'::uuid, 'b6cb74f3-513b-5522-8269-8df467af6307'::uuid, 'Comment se calcule le PIB ?', 'mcq', '["Par la somme des valeurs ajoutées des unités résidentes","Par la somme des chiffres d’affaires","Par la somme des salaires","Par le total des exportations"]'::jsonb, 0, 'On y ajoute la TVA et les droits de douane.', 1),
    ('137dc03d-6225-5c3e-b47a-4e34a982b18b'::uuid, 'b6cb74f3-513b-5522-8269-8df467af6307'::uuid, 'Que signifie intérieur dans produit intérieur brut ?', 'mcq', '["Ce qui est produit sur le territoire, quelle que soit la nationalité du producteur","Ce qui est produit par les nationaux, où qu’ils soient","Ce qui est consommé dans le pays","Ce qui n’est pas exporté"]'::jsonb, 0, 'À distinguer du produit national brut.', 2),
    ('5df76cfe-6fd7-56c4-9e69-ef9c4139ac94'::uuid, 'b6cb74f3-513b-5522-8269-8df467af6307'::uuid, 'Quel PIB sert à mesurer la croissance économique ?', 'mcq', '["Le PIB en volume, qui neutralise l’inflation","Le PIB en valeur","Le PIB par habitant","Le PIB nominal"]'::jsonb, 0, 'Sinon, une simple hausse des prix passerait pour de la croissance.', 3),
    ('927234a3-d5ce-5009-8de5-60583aa8e81d'::uuid, 'b6cb74f3-513b-5522-8269-8df467af6307'::uuid, 'Le travail domestique est-il compté dans le PIB ?', 'mcq', '["Non, il n’est pas rémunéré ni échangé","Oui, à son coût estimé","Oui, depuis 2000","Oui, dans les pays de l’OCDE seulement"]'::jsonb, 0, 'Une critique majeure de l’indicateur.', 4),
    ('00147b4e-09c9-5ff9-b14c-088b58ceeb89'::uuid, 'b6cb74f3-513b-5522-8269-8df467af6307'::uuid, 'Une marée noire peut-elle augmenter le PIB ?', 'mcq', '["Oui, par les dépenses de dépollution qu’elle engendre","Non, elle le fait toujours baisser","Non, elle est neutre","Oui, mais seulement à long terme"]'::jsonb, 0, 'Le PIB compte l’activité, pas le bien-être.', 5),
    ('40be6468-b99c-5de6-a6a6-810e59d0fd85'::uuid, 'b6cb74f3-513b-5522-8269-8df467af6307'::uuid, 'Le PIB par habitant renseigne-t-il sur la répartition des richesses ?', 'mcq', '["Non, c’est une moyenne","Oui, précisément","Oui, s’il est calculé en volume","Non, il ne se calcule pas"]'::jsonb, 0, 'Il faut l’indice de Gini pour mesurer les inégalités.', 6),
    ('c61fe10c-9384-503e-85f5-9495f423de34'::uuid, 'b6cb74f3-513b-5522-8269-8df467af6307'::uuid, 'Quel indicateur ajoute la santé et l’éducation au niveau de vie ?', 'mcq', '["L’IDH","L’empreinte écologique","L’indice de Gini","Le PIB en volume"]'::jsonb, 0, 'Publié chaque année par le PNUD.', 7),
    ('334e54da-f1d5-59a9-bc53-6dfaa4c2f23f'::uuid, 'b6cb74f3-513b-5522-8269-8df467af6307'::uuid, 'Que mesure l’empreinte écologique ?', 'mcq', '["La pression exercée par une population sur la biosphère","Les émissions de gaz à effet de serre uniquement","La surface agricole d’un pays","Le coût de la dépollution"]'::jsonb, 0, 'Elle s’exprime en hectares globaux par habitant.', 8),
    ('96403663-b11a-5a95-a441-d5562a2da378'::uuid, '1bc94836-f430-554d-890b-537383e6910f'::uuid, 'Comment mesure-t-on la croissance économique ?', 'mcq', '["Par la variation du PIB en volume","Par la variation des prix","Par le nombre d’emplois créés","Par la hausse des exportations"]'::jsonb, 0, 'En volume, pour neutraliser l’inflation.', 1),
    ('d16e4eca-18f6-5032-8b6d-ce0ce56fdc46'::uuid, '1bc94836-f430-554d-890b-537383e6910f'::uuid, 'Quelle différence entre croissance et développement ?', 'mcq', '["Le développement inclut les transformations sociales et le niveau de vie","Ce sont deux synonymes","La croissance est plus longue","Le développement ne concerne que les pays pauvres"]'::jsonb, 0, 'On peut avoir de la croissance sans développement.', 2),
    ('5b362d92-aa2c-5d5c-b0f8-85c8fa3b7559'::uuid, '1bc94836-f430-554d-890b-537383e6910f'::uuid, 'Quand la croissance économique moderne commence-t-elle ?', 'mcq', '["Avec la révolution industrielle, à la fin du XVIIIe siècle","Au Moyen Âge","Après 1945 seulement","Au XVIe siècle"]'::jsonb, 0, 'Avant, la production stagnait ou progressait très lentement.', 3),
    ('de4db39e-ca8a-5c23-bb23-4982c5f63fa7'::uuid, '1bc94836-f430-554d-890b-537383e6910f'::uuid, 'Qu’appelle-t-on les Trente Glorieuses ?', 'mcq', '["La période de forte croissance de 1945 à 1975","Les trente années suivant 1929","La période 1980-2010","Le XIXe siècle industriel"]'::jsonb, 0, 'Des taux annuels autour de 5 % en France.', 4),
    ('8d6dff81-5adb-5703-a5b3-973518115c7d'::uuid, '1bc94836-f430-554d-890b-537383e6910f'::uuid, 'Qu’est-ce qu’une récession ?', 'mcq', '["Un recul du PIB pendant au moins deux trimestres consécutifs","Une baisse des prix","Une hausse du chômage","Une croissance faible mais positive"]'::jsonb, 0, 'La dépression est une récession longue et profonde.', 5),
    ('22dde31f-2d77-56ed-b5dd-6af5046260df'::uuid, '1bc94836-f430-554d-890b-537383e6910f'::uuid, 'La croissance a concerné toutes les régions du monde en même temps.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Europe et Amérique du Nord d’abord, émergents ensuite.', 6),
    ('f5ef478e-a477-5e7d-8b31-9dbdae6b6eb0'::uuid, '1bc94836-f430-554d-890b-537383e6910f'::uuid, 'À quel rythme une croissance de 2 % par an double-t-elle la production ?', 'mcq', '["En trente-cinq ans environ","En cinquante ans","En dix ans","En un siècle"]'::jsonb, 0, 'L’effet des intérêts composés.', 7),
    ('c30d9af3-f774-54ea-b593-a5d5bf02d5c9'::uuid, '1bc94836-f430-554d-890b-537383e6910f'::uuid, 'Quel événement mondial a provoqué une forte récession en 2020 ?', 'mcq', '["La crise sanitaire","Une crise pétrolière","Un krach immobilier","Une guerre commerciale"]'::jsonb, 0, 'Après celles de 1973, 1979 et 2008.', 8),
    ('69def0b1-c78d-5441-89b9-217a9d0b3746'::uuid, 'c00db5e4-37d4-5f58-a764-6848e444eee2'::uuid, 'Qu’est-ce qu’une externalité négative ?', 'mcq', '["Un effet non payé qu’une activité impose à autrui","Une taxe sur la pollution","Un coût de production élevé","Une importation polluante"]'::jsonb, 0, 'La pollution d’une rivière par une usine en est l’exemple type.', 1),
    ('b163f6a4-438c-5ea4-ba19-057a1a9accd7'::uuid, 'c00db5e4-37d4-5f58-a764-6848e444eee2'::uuid, 'Pourquoi l’atmosphère est-elle un bien commun difficile à protéger ?', 'mcq', '["Chacun a intérêt à l’utiliser sans supporter le coût de sa dégradation","Elle appartient à un seul État","Elle est illimitée","Elle est protégée par le marché"]'::jsonb, 0, 'Aucun acteur isolé n’a intérêt à s’imposer un effort.', 2),
    ('7ec00ff1-0bb1-5b97-b043-c488f6b1e4b9'::uuid, 'c00db5e4-37d4-5f58-a764-6848e444eee2'::uuid, 'Que dit le principe pollueur-payeur ?', 'mcq', '["Celui qui pollue doit supporter le coût de la pollution","L’État paie la dépollution","Le consommateur choisit librement","Les entreprises se régulent elles-mêmes"]'::jsonb, 0, 'Il justifie taxes et redevances environnementales.', 3),
    ('8f0a2ef7-a4db-5bde-8e06-84338ebfeb91'::uuid, 'c00db5e4-37d4-5f58-a764-6848e444eee2'::uuid, 'Qu’est-ce que le développement durable ?', 'mcq', '["Un développement qui répond aux besoins présents sans compromettre ceux des générations futures","Une croissance rapide et continue","L’arrêt de toute croissance","La protection des seules forêts"]'::jsonb, 0, 'Définition du rapport Brundtland, 1987.', 4),
    ('2b0feb4f-a8c1-5f25-a4da-e32801ce1535'::uuid, 'c00db5e4-37d4-5f58-a764-6848e444eee2'::uuid, 'Quel rapport de 1972 alerte sur les limites de la croissance ?', 'mcq', '["Le rapport Meadows","Le rapport Brundtland","Le protocole de Kyoto","Le rapport Stern"]'::jsonb, 0, 'Commandé par le Club de Rome.', 5),
    ('772a4152-6293-502b-b4df-148c4ce8ac17'::uuid, 'c00db5e4-37d4-5f58-a764-6848e444eee2'::uuid, 'Le marché carbone repose sur des quotas d’émission échangeables.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le plafond baisse, ce qui rend le droit à polluer plus cher.', 6),
    ('b94201f8-8df1-598c-87bf-7f0be836e3d8'::uuid, 'c00db5e4-37d4-5f58-a764-6848e444eee2'::uuid, 'Que défend la thèse de la croissance verte ?', 'mcq', '["Qu’on peut découpler croissance et dégradation grâce au progrès technique","Qu’il faut réduire la production","Que la croissance n’a aucun effet écologique","Que seule la réglementation compte"]'::jsonb, 0, 'La décroissance conteste la possibilité d’un découplage suffisant.', 7),
    ('5116aa7f-d64d-5af9-ac4d-4a906a77e027'::uuid, 'c00db5e4-37d4-5f58-a764-6848e444eee2'::uuid, 'Quelle ressource est renouvelable mais surexploitée ?', 'mcq', '["Les stocks de poissons","Le pétrole","Le gaz naturel","Le charbon"]'::jsonb, 0, 'Une ressource renouvelable peut disparaître si le prélèvement dépasse le renouvellement.', 8),
    ('25cefcda-cf4b-5aac-9f10-2c63063f9994'::uuid, 'd2233da3-f85d-5408-902c-fe406125255b'::uuid, 'Qu’est-ce qu’un marché en économie ?', 'mcq', '["La rencontre d’une offre et d’une demande aboutissant à un prix","Un lieu physique de vente","Un magasin","Une entreprise en situation de monopole"]'::jsonb, 0, 'Il peut être totalement dématérialisé.', 1),
    ('e06f8be4-71b8-5cfc-b89d-169816e4c298'::uuid, 'd2233da3-f85d-5408-902c-fe406125255b'::uuid, 'Quelles institutions sont nécessaires à l’échange marchand ?', 'mcq', '["Des droits de propriété, une monnaie et des contrats garantis","Une administration douanière","Une bourse des valeurs","Un syndicat professionnel"]'::jsonb, 0, 'Sans confiance ni règles, l’échange ne se fait pas.', 2),
    ('f8955c36-7653-523b-be21-5b670c4dd3f3'::uuid, 'd2233da3-f85d-5408-902c-fe406125255b'::uuid, 'Que suppose la concurrence parfaite ?', 'mcq', '["De nombreux offreurs et demandeurs, des produits homogènes et une information parfaite","Un seul offreur puissant","Des produits très différenciés","Des barrières à l’entrée"]'::jsonb, 0, 'C’est un modèle théorique, rarement observé.', 3),
    ('be457d84-988d-5faa-8b5e-39a4c14bdad3'::uuid, 'd2233da3-f85d-5408-902c-fe406125255b'::uuid, 'Qu’est-ce qu’un oligopole ?', 'mcq', '["Un marché dominé par un petit nombre d’offreurs","Un marché à offreur unique","Un marché sans acheteur","Un marché réglementé par l’État"]'::jsonb, 0, 'Téléphonie, aéronautique, distribution en donnent des exemples.', 4),
    ('e9133c20-333c-5af9-bf90-42532d805a4d'::uuid, 'd2233da3-f85d-5408-902c-fe406125255b'::uuid, 'Qu’est-ce que la concurrence monopolistique ?', 'mcq', '["De nombreux offreurs proposant des produits différenciés","Un monopole légal","Un marché sans concurrence","Un duopole"]'::jsonb, 0, 'La marque, la qualité ou l’image créent un pouvoir de marché limité.', 5),
    ('9868bab5-7eaa-54d3-b50f-4b69ba335bdf'::uuid, 'd2233da3-f85d-5408-902c-fe406125255b'::uuid, 'Les ententes sur les prix entre entreprises sont interdites.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles sont sanctionnées par les autorités de la concurrence.', 6),
    ('ee34cc33-e899-5f3d-93cf-c48ee12ce3c6'::uuid, 'd2233da3-f85d-5408-902c-fe406125255b'::uuid, 'Tous les biens peuvent-ils être échangés sur un marché ?', 'mcq', '["Non, certains échanges sont interdits par la loi","Oui, si un prix existe","Oui, sauf les services publics","Non, seuls les biens matériels le peuvent"]'::jsonb, 0, 'Organes, voix électorales, diplômes : le marché a des frontières morales et légales.', 7),
    ('b741ecff-2c5a-5ce6-828f-fe8263bfe1a7'::uuid, 'd2233da3-f85d-5408-902c-fe406125255b'::uuid, 'Que fait une autorité de la concurrence ?', 'mcq', '["Elle sanctionne les ententes et les abus de position dominante","Elle fixe les prix","Elle finance les entreprises","Elle recrute les salariés"]'::jsonb, 0, 'Elle contrôle aussi les fusions et concentrations.', 8),
    ('7cd3c727-3fa4-505f-9235-86c30737c580'::uuid, 'f888ba2f-bf5d-52be-9345-305e2f87df01'::uuid, 'Comment évolue la demande quand le prix augmente ?', 'mcq', '["Elle diminue","Elle augmente","Elle reste constante","Elle devient nulle"]'::jsonb, 0, 'La courbe de demande est décroissante.', 1),
    ('33c956f4-89de-58fc-be12-fc63bcad5d4f'::uuid, 'f888ba2f-bf5d-52be-9345-305e2f87df01'::uuid, 'Comment évolue l’offre quand le prix augmente ?', 'mcq', '["Elle augmente","Elle diminue","Elle reste constante","Elle devient nulle"]'::jsonb, 0, 'Produire devient plus rentable pour davantage de producteurs.', 2),
    ('8d441059-6740-5255-9028-857a895947f7'::uuid, 'f888ba2f-bf5d-52be-9345-305e2f87df01'::uuid, 'Qu’est-ce que le prix d’équilibre ?', 'mcq', '["Le prix pour lequel la quantité offerte égale la quantité demandée","Le prix le plus bas du marché","Le prix fixé par l’État","Le prix moyen constaté"]'::jsonb, 0, 'À ce prix, il n’y a ni pénurie ni invendus.', 3),
    ('8f053c13-4954-5fc7-a169-e2452ebb57ba'::uuid, 'f888ba2f-bf5d-52be-9345-305e2f87df01'::uuid, 'Que se passe-t-il si le prix est supérieur au prix d’équilibre ?', 'mcq', '["L’offre excède la demande, ce qui pousse le prix à la baisse","La demande excède l’offre","Le marché disparaît","Rien ne change"]'::jsonb, 0, 'Les invendus obligent les vendeurs à baisser leur prix.', 4),
    ('8db1d86c-a265-5c62-ac1a-d4f2a2e893eb'::uuid, 'f888ba2f-bf5d-52be-9345-305e2f87df01'::uuid, 'Qu’est-ce qui déplace la courbe de demande ?', 'mcq', '["Une variation du revenu ou des goûts","Une variation du prix du bien lui-même","Un progrès technique du producteur","Une taxe sur la production"]'::jsonb, 0, 'Le prix du bien fait se déplacer le long de la courbe, pas la courbe.', 5),
    ('98be3be4-823b-56f8-8b54-c9745d760f82'::uuid, 'f888ba2f-bf5d-52be-9345-305e2f87df01'::uuid, 'Une élasticité-prix faible signifie que la demande varie peu quand le prix change.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le cas des produits de première nécessité.', 6),
    ('9fddec5a-1353-5fef-915d-10681eb89206'::uuid, 'f888ba2f-bf5d-52be-9345-305e2f87df01'::uuid, 'Pourquoi le prix est-il une information ?', 'mcq', '["Il indique aux producteurs quoi produire et aux consommateurs à quoi renoncer","Il fixe le salaire des employés","Il détermine le taux d’imposition","Il mesure la qualité du bien"]'::jsonb, 0, 'C’est le signal central du fonctionnement du marché.', 7),
    ('ed8adc83-b1d6-5237-92ed-7acb457e5f53'::uuid, 'f888ba2f-bf5d-52be-9345-305e2f87df01'::uuid, 'Une taxe sur un produit déplace quelle courbe ?', 'mcq', '["La courbe d’offre","La courbe de demande","Les deux à la fois","Aucune des deux"]'::jsonb, 0, 'Elle augmente le coût pour le producteur à chaque niveau de prix.', 8),
    ('747e8d7e-cead-54de-bae0-374e41c6d685'::uuid, '941905b6-3cff-5dad-a0b2-2df3c90229e7'::uuid, 'Qu’est-ce qu’une défaillance de marché ?', 'mcq', '["Une situation où le marché aboutit à un résultat collectivement inefficace","Une faillite d’entreprise","Un krach boursier","Une pénurie temporaire"]'::jsonb, 0, 'Les externalités en sont l’exemple central.', 1),
    ('567ff51e-be28-55f7-b6c5-12d7f5a9a7df'::uuid, '941905b6-3cff-5dad-a0b2-2df3c90229e7'::uuid, 'Pourquoi le prix d’un produit polluant est-il trop bas ?', 'mcq', '["Il n’intègre pas le coût de la pollution supportée par tous","Il est fixé par l’État","Les coûts de production sont sous-estimés","La demande est trop faible"]'::jsonb, 0, 'D’où une production supérieure à l’optimum social.', 2),
    ('00a11cdb-5d4c-571c-b4fe-74566585a161'::uuid, '941905b6-3cff-5dad-a0b2-2df3c90229e7'::uuid, 'Quels sont les trois grands instruments de la politique environnementale ?', 'mcq', '["Réglementation, taxation et marché de quotas","Subvention, nationalisation et privatisation","Impôt, dette et dépense publique","Norme, publicité et information"]'::jsonb, 0, 'Ils sont souvent combinés.', 3),
    ('2c560fc6-ca86-5cc1-a8a4-2e4d61ef211b'::uuid, '941905b6-3cff-5dad-a0b2-2df3c90229e7'::uuid, 'Que fixe un marché de quotas d’émission ?', 'mcq', '["Une quantité maximale d’émissions, le prix résultant des échanges","Un prix du carbone, la quantité s’ajustant","Une interdiction totale","Une subvention aux entreprises propres"]'::jsonb, 0, 'La taxe fait l’inverse : elle fixe le prix.', 4),
    ('86be3b19-95d1-594d-b645-76d2b6aa3b31'::uuid, '941905b6-3cff-5dad-a0b2-2df3c90229e7'::uuid, 'Que reproche-t-on souvent à une taxe environnementale ?', 'mcq', '["D’être régressive et de peser davantage sur les ménages modestes","D’être inefficace","De ne rapporter aucune recette","D’être illégale"]'::jsonb, 0, 'D’où la nécessité de compensations.', 5),
    ('5b3d4cff-2a53-5150-a9e2-7f6964e15a77'::uuid, '941905b6-3cff-5dad-a0b2-2df3c90229e7'::uuid, 'La réglementation est plus souple que la taxation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle impose la même contrainte à tous, quel que soit le coût pour chacun.', 6),
    ('2dfa1caf-deaf-51a8-90fe-b397efef7396'::uuid, '941905b6-3cff-5dad-a0b2-2df3c90229e7'::uuid, 'Quel mouvement social de 2018 est lié à une hausse des taxes sur les carburants ?', 'mcq', '["Les gilets jaunes","Les bonnets rouges","Nuit debout","Les zadistes"]'::jsonb, 0, 'L’acceptabilité conditionne l’efficacité d’une politique.', 7),
    ('fd14e801-b512-553e-8e6f-693253837022'::uuid, '941905b6-3cff-5dad-a0b2-2df3c90229e7'::uuid, 'Qu’est-ce qu’un malus automobile ?', 'mcq', '["Une taxe à l’achat d’un véhicule très émetteur","Une amende de circulation","Une prime à la casse","Un péage urbain"]'::jsonb, 0, 'Un exemple concret du principe pollueur-payeur.', 8),
    ('a5f61d2d-5bee-50ac-a16b-3956e07f78db'::uuid, '6d8c0fb4-6e45-585f-a8d9-18947f156efc'::uuid, 'Qu’est-ce que la socialisation ?', 'mcq', '["Le processus d’intériorisation des normes, valeurs et rôles d’une société","L’intégration dans un groupe d’amis","L’apprentissage d’un métier","La participation à la vie associative"]'::jsonb, 0, 'Elle est continue, mais son moment le plus décisif est l’enfance.', 1),
    ('646a93ce-9e00-5c2c-a216-8bb665c5cbcd'::uuid, '6d8c0fb4-6e45-585f-a8d9-18947f156efc'::uuid, 'Quelle différence entre une norme et une valeur ?', 'mcq', '["La norme est une règle de comportement, la valeur un idéal qui la justifie","Ce sont deux synonymes","La norme est juridique, la valeur morale","La valeur est individuelle, la norme collective"]'::jsonb, 0, 'La ponctualité est une norme, le respect d’autrui une valeur.', 2),
    ('9460547f-6efc-533f-9f9d-168b04e784ba'::uuid, '6d8c0fb4-6e45-585f-a8d9-18947f156efc'::uuid, 'Qu’est-ce qu’un rôle social ?', 'mcq', '["L’ensemble des comportements attendus d’une position sociale","Un métier","Une personnalité","Une fonction politique"]'::jsonb, 0, 'On attend d’un élève, d’un médecin ou d’un parent certains comportements.', 3),
    ('5f419c84-9f85-59c7-8cc2-e7767cdfb69a'::uuid, '6d8c0fb4-6e45-585f-a8d9-18947f156efc'::uuid, 'Quelle socialisation est la plus durable ?', 'mcq', '["La socialisation primaire, dans l’enfance","La socialisation secondaire","La socialisation professionnelle","La socialisation par les médias"]'::jsonb, 0, 'Elle façonne la langue, les manières et les repères moraux.', 4),
    ('b73150e9-9109-57e9-86bc-f4052a1bf628'::uuid, '6d8c0fb4-6e45-585f-a8d9-18947f156efc'::uuid, 'Les instances de socialisation transmettent-elles toujours les mêmes messages ?', 'mcq', '["Non, elles peuvent être contradictoires","Oui, toujours","Oui, sauf les médias","Non, elles ne transmettent rien"]'::jsonb, 0, 'L’individu compose entre des influences parfois opposées.', 5),
    ('4e55eab6-b0d5-5db5-8960-161a3f0b5f5b'::uuid, '6d8c0fb4-6e45-585f-a8d9-18947f156efc'::uuid, 'L’imprégnation implicite est souvent plus puissante que l’inculcation explicite.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Parce qu’elle passe inaperçue et ne suscite pas de résistance.', 6),
    ('17787739-cb5c-5e9d-be1e-1ee9429c5a0b'::uuid, '6d8c0fb4-6e45-585f-a8d9-18947f156efc'::uuid, 'Qu’est-ce que la socialisation secondaire ?', 'mcq', '["Celle qui se poursuit à l’âge adulte, au travail ou en couple","Celle qui a lieu à l’école primaire","Celle qui vient des grands-parents","Celle qui est imposée par la loi"]'::jsonb, 0, 'Elle peut entrer en tension avec la socialisation primaire.', 7),
    ('0f011f87-dcb4-55cd-a03e-2611fe94010b'::uuid, '6d8c0fb4-6e45-585f-a8d9-18947f156efc'::uuid, 'L’individu est-il passif face à la socialisation ?', 'mcq', '["Non, il sélectionne, réinterprète et résiste parfois","Oui, il subit entièrement","Oui, jusqu’à la majorité","Non, il n’est pas socialisé"]'::jsonb, 0, 'La socialisation n’est pas un formatage.', 8),
    ('5a729c45-1e29-56d6-ab7a-8288b8072005'::uuid, '85784226-9f70-5a09-972e-8d442a49f21d'::uuid, 'Qu’est-ce que l’identité sociale ?', 'mcq', '["La manière dont un individu se définit et est défini par ses appartenances","Le numéro de sécurité sociale","La personnalité psychologique","La nationalité"]'::jsonb, 0, 'Elle se construit dans l’interaction avec les autres.', 1),
    ('9539707d-09c1-5048-aad1-11c0365a2ba9'::uuid, '85784226-9f70-5a09-972e-8d442a49f21d'::uuid, 'Qu’est-ce qu’un groupe de référence ?', 'mcq', '["Un groupe auquel on aspire et dont on adopte les manières","Le groupe auquel on appartient","Un groupe imposé par la loi","Un groupe de travail"]'::jsonb, 0, 'Il peut différer du groupe d’appartenance.', 2),
    ('daeaf5ac-0bb1-5a87-a8d9-0358021cc85e'::uuid, '85784226-9f70-5a09-972e-8d442a49f21d'::uuid, 'Qu’appelle-t-on habitus chez Bourdieu ?', 'mcq', '["Un ensemble de dispositions incorporées qui orientent les pratiques","Une habitude consciente","Un règlement intérieur","Un mode de vie choisi"]'::jsonb, 0, 'Il agit sans que l’individu ait besoin d’y penser.', 3),
    ('48103f67-3562-57df-bba5-103af8de10c3'::uuid, '85784226-9f70-5a09-972e-8d442a49f21d'::uuid, 'Qu’est-ce qu’un conflit de rôles ?', 'mcq', '["Une contradiction entre les attentes liées à deux positions occupées simultanément","Une dispute entre collègues","Un désaccord politique","Une crise d’adolescence"]'::jsonb, 0, 'Exigences professionnelles contre exigences familiales, par exemple.', 4),
    ('eae284f7-2fd1-526f-a8b4-99865b010516'::uuid, '85784226-9f70-5a09-972e-8d442a49f21d'::uuid, 'Qu’est-ce que la socialisation anticipatrice ?', 'mcq', '["Adopter d’avance les codes d’un groupe que l’on souhaite rejoindre","Socialiser un enfant très tôt","Prévoir sa retraite","Changer de milieu par obligation"]'::jsonb, 0, 'Un étudiant qui adopte les manières du métier visé.', 5),
    ('e7844150-b009-5432-aa93-e9146d55f9cc'::uuid, '85784226-9f70-5a09-972e-8d442a49f21d'::uuid, 'L’identité sociale est fixée une fois pour toutes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle évolue, et une resocialisation peut la transformer profondément.', 6),
    ('22fe95f9-281c-59cd-a365-5d7b031249c2'::uuid, '85784226-9f70-5a09-972e-8d442a49f21d'::uuid, 'Qu’est-ce qu’une resocialisation ?', 'mcq', '["Une transformation profonde des normes et rôles intériorisés","Un retour à l’école","Un déménagement","Une reconversion sans changement de milieu"]'::jsonb, 0, 'Armée, conversion, immigration en sont des exemples.', 7),
    ('5d89af88-f24b-56d1-8dbc-a4bc4bd9e4e2'::uuid, '85784226-9f70-5a09-972e-8d442a49f21d'::uuid, 'Pourquoi deux élèves aux mêmes résultats peuvent-ils choisir des voies différentes ?', 'mcq', '["Leurs dispositions socialisées orientent ce qu’ils jugent possible pour eux","L’un est plus intelligent","Les notes ne comptent pas","Le hasard décide"]'::jsonb, 0, 'L’autocensure est un effet bien documenté de la socialisation.', 8),
    ('2da82bfa-29d5-5135-8958-1e93b43569a8'::uuid, '0a929cb7-1bc3-5f85-9132-d97b37cd6ccc'::uuid, 'Quelle différence entre sexe et genre ?', 'mcq', '["Le sexe est biologique, le genre est une construction sociale","Ce sont deux synonymes","Le genre est juridique","Le sexe est déclaratif"]'::jsonb, 0, 'Le genre désigne les rôles associés au masculin et au féminin.', 1),
    ('3141ca58-06a3-590d-9d24-37f0edd512ee'::uuid, '0a929cb7-1bc3-5f85-9132-d97b37cd6ccc'::uuid, 'Comment sait-on que les rôles de genre ne sont pas naturels ?', 'mcq', '["Ils varient selon les époques et les sociétés","Ils sont identiques partout","Ils sont fixés par la loi","Ils ne varient qu’avec l’âge"]'::jsonb, 0, 'La variabilité est l’argument central.', 2),
    ('159534d9-1187-55fa-8750-c76407ee3891'::uuid, '0a929cb7-1bc3-5f85-9132-d97b37cd6ccc'::uuid, 'Où se lit la socialisation différenciée selon le genre ?', 'mcq', '["Dans les choix d’orientation et le partage du travail domestique","Uniquement dans les salaires","Uniquement dans le sport","Nulle part de façon mesurable"]'::jsonb, 0, 'Filles majoritaires en santé, minoritaires en informatique.', 3),
    ('e57c4a71-6678-5c16-b2c5-93babfb01f4d'::uuid, '0a929cb7-1bc3-5f85-9132-d97b37cd6ccc'::uuid, 'Qu’est-ce que le capital culturel ?', 'mcq', '["Les savoirs, références et aisances transmis par la famille et valorisés à l’école","Le budget culturel d’un ménage","Le patrimoine artistique d’un pays","Le nombre de livres publiés"]'::jsonb, 0, 'Il avantage certains élèves sans qu’aucune règle ne le prévoie.', 4),
    ('f9e7b3db-34ec-59dd-bceb-e06edfab7e1d'::uuid, '0a929cb7-1bc3-5f85-9132-d97b37cd6ccc'::uuid, 'Qu’appelle-t-on reproduction sociale ?', 'mcq', '["La tendance des positions sociales à se transmettre d’une génération à l’autre","La croissance démographique","Le renouvellement des générations","La mobilité professionnelle"]'::jsonb, 0, 'La socialisation différenciée en est un mécanisme central.', 5),
    ('d94ec21a-2f48-5099-800e-1a24a71d58e5'::uuid, '0a929cb7-1bc3-5f85-9132-d97b37cd6ccc'::uuid, 'La socialisation différenciée rend toute mobilité sociale impossible.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle rend certaines trajectoires plus probables, pas certaines.', 6),
    ('af9bf016-779a-58cf-967f-83c6fce61905'::uuid, '0a929cb7-1bc3-5f85-9132-d97b37cd6ccc'::uuid, 'Qu’est-ce qui différencie les pratiques éducatives selon le milieu ?', 'mcq', '["Le rapport au langage, à la lecture, aux loisirs et à l’autorité","Le nombre d’enfants","La région d’habitation seulement","La taille du logement"]'::jsonb, 0, 'Ces différences ont des effets scolaires mesurables.', 7),
    ('1a666617-b6df-5507-91ce-ad4baa4ad767'::uuid, '0a929cb7-1bc3-5f85-9132-d97b37cd6ccc'::uuid, 'Les jouets proposés aux enfants participent-ils à la socialisation de genre ?', 'mcq', '["Oui, ils orientent les activités et les compétences valorisées","Non, ils sont neutres","Oui, mais seulement après six ans","Non, seuls les parents comptent"]'::jsonb, 0, 'Couleurs, catalogues et rayons différenciés dès la petite enfance.', 8),
    ('c9ee886b-2674-514c-a161-6333602f387d'::uuid, '00d89bde-0f3b-57a0-b028-51e00dcedca7'::uuid, 'Quels critères définissent un régime démocratique ?', 'mcq', '["Élections libres, séparation des pouvoirs, libertés fondamentales et État de droit","La seule tenue d’élections","Un parti unique fort","Un référendum annuel"]'::jsonb, 0, 'Les élections seules ne suffisent pas.', 1),
    ('f77a5012-8e38-5a4f-93d7-c99ef1d71423'::uuid, '00d89bde-0f3b-57a0-b028-51e00dcedca7'::uuid, 'Qu’est-ce que l’État de droit ?', 'mcq', '["Un système où tous, y compris les gouvernants, sont soumis à la loi","Un État qui édicte beaucoup de lois","Un État centralisé","Un régime présidentiel"]'::jsonb, 0, 'Il suppose une justice indépendante.', 2),
    ('f028b830-a930-507a-b39a-ad71a858547c'::uuid, '00d89bde-0f3b-57a0-b028-51e00dcedca7'::uuid, 'Quelle forme de démocratie domine aujourd’hui ?', 'mcq', '["La démocratie représentative","La démocratie directe","La démocratie participative","La démocratie censitaire"]'::jsonb, 0, 'Les citoyens élisent ceux qui décident en leur nom.', 3),
    ('407c7e94-68c8-52cb-b44f-4e5f0da9c241'::uuid, '00d89bde-0f3b-57a0-b028-51e00dcedca7'::uuid, 'Qu’est-ce qu’un budget participatif ?', 'mcq', '["Un dispositif où les habitants décident de l’affectation d’une part du budget local","Le budget voté par le Parlement","Un emprunt public","Une consultation des entreprises"]'::jsonb, 0, 'Il relève de la démocratie participative.', 4),
    ('82e918e1-0e27-5c68-9902-0305d2cd4b96'::uuid, '00d89bde-0f3b-57a0-b028-51e00dcedca7'::uuid, 'Pourquoi les contre-pouvoirs sont-ils essentiels ?', 'mcq', '["Ils empêchent la concentration du pouvoir","Ils accélèrent les décisions","Ils remplacent les élections","Ils réduisent les dépenses publiques"]'::jsonb, 0, 'Justice, presse, Parlement, associations, autorités indépendantes.', 5),
    ('c3021f2d-71c7-5802-84d0-b62c37cfb317'::uuid, '00d89bde-0f3b-57a0-b028-51e00dcedca7'::uuid, 'Un régime qui organise des élections est nécessairement démocratique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les régimes hybrides gardent les élections en vidant les libertés.', 6),
    ('c29b49a1-77bc-5429-9ad4-eb9392992ab6'::uuid, '00d89bde-0f3b-57a0-b028-51e00dcedca7'::uuid, 'Que garantit le suffrage universel ?', 'mcq', '["Le droit de vote à tous les citoyens majeurs, sans condition de fortune","Le vote obligatoire","Le vote électronique","La représentation proportionnelle"]'::jsonb, 0, 'Il s’oppose au suffrage censitaire.', 7),
    ('6429e132-eaee-5ed6-bfd9-dad62f26f1f9'::uuid, '00d89bde-0f3b-57a0-b028-51e00dcedca7'::uuid, 'Qu’est-ce qui menace aujourd’hui les démocraties selon le programme ?', 'mcq', '["Abstention, défiance et désinformation","L’excès de contre-pouvoirs","La liberté de la presse","Le pluralisme des partis"]'::jsonb, 0, 'La démocratie s’entretient, elle n’est jamais acquise.', 8),
    ('de6f508d-19c7-57f0-a25c-7a9ee00d0839'::uuid, 'e9f303ca-9982-5fd7-9834-24cd762ce593'::uuid, 'De quand date la Constitution de la Ve République ?', 'mcq', '["Du 4 octobre 1958","Du 27 octobre 1946","Du 14 juillet 1958","Du 28 septembre 1962"]'::jsonb, 0, 'Elle est adoptée par référendum.', 1),
    ('fef1a3e5-39ba-5a8f-8e96-05cc727b2ea7'::uuid, 'e9f303ca-9982-5fd7-9834-24cd762ce593'::uuid, 'Depuis quelle réforme le président est-il élu au suffrage universel direct ?', 'mcq', '["Depuis 1962","Depuis 1958","Depuis 2000","Depuis 2008"]'::jsonb, 0, 'Un référendum voulu par de Gaulle.', 2),
    ('d96ef7e9-feb7-5b92-8e4d-bc03d376dfaa'::uuid, 'e9f303ca-9982-5fd7-9834-24cd762ce593'::uuid, 'Combien de députés compte l’Assemblée nationale ?', 'mcq', '["577","348","500","925"]'::jsonb, 0, 'Élus au scrutin uninominal majoritaire à deux tours.', 3),
    ('c69c3ce1-23f2-5198-a41d-38d120945f49'::uuid, 'e9f303ca-9982-5fd7-9834-24cd762ce593'::uuid, 'Comment les sénateurs sont-ils élus ?', 'mcq', '["Au suffrage indirect, par de grands électeurs","Au suffrage universel direct","Par le président","Par tirage au sort"]'::jsonb, 0, 'Pour six ans, avec renouvellement par moitié.', 4),
    ('7e720de7-c0fb-5ae9-9751-de0e8c3e1bcc'::uuid, 'e9f303ca-9982-5fd7-9834-24cd762ce593'::uuid, 'Devant qui le gouvernement est-il responsable ?', 'mcq', '["Devant l’Assemblée nationale","Devant le Sénat","Devant le président seul","Devant le Conseil constitutionnel"]'::jsonb, 0, 'Elle peut le renverser par une motion de censure.', 5),
    ('765da5df-3d06-5636-8988-a9002310b824'::uuid, 'e9f303ca-9982-5fd7-9834-24cd762ce593'::uuid, 'La question prioritaire de constitutionnalité existe depuis 2008.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle permet à un justiciable de contester une loi déjà en vigueur.', 6),
    ('ea423e77-1eda-503e-a55e-af9e174b230f'::uuid, 'e9f303ca-9982-5fd7-9834-24cd762ce593'::uuid, 'Qu’est-ce qu’une cohabitation ?', 'mcq', '["Un président et une majorité parlementaire de camps opposés","Un gouvernement d’union nationale","Une alliance entre deux partis","Un partage entre Assemblée et Sénat"]'::jsonb, 0, 'Elle s’est produite trois fois sous la Ve République.', 7),
    ('601a10de-0b20-5f4a-884b-9557ceb427e2'::uuid, 'e9f303ca-9982-5fd7-9834-24cd762ce593'::uuid, 'Comment qualifie-t-on le régime de la Ve République ?', 'mcq', '["Semi-présidentiel","Présidentiel","Parlementaire classique","Directorial"]'::jsonb, 0, 'Il emprunte aux deux modèles.', 8),
    ('b85183a7-b796-5b5b-9fb8-19cc2d3c7261'::uuid, '8d1a293e-3257-5674-8f42-e139497cb150'::uuid, 'Quel mode de scrutin est utilisé pour les élections législatives françaises ?', 'mcq', '["Le scrutin uninominal majoritaire à deux tours","La proportionnelle intégrale","Le scrutin de liste à un tour","Le vote préférentiel"]'::jsonb, 0, 'Une circonscription, un siège.', 1),
    ('8e8c74cc-9c90-511e-ad68-08180b6497dd'::uuid, '8d1a293e-3257-5674-8f42-e139497cb150'::uuid, 'Quel est le principal avantage du scrutin majoritaire ?', 'mcq', '["Il dégage des majorités claires et stables","Il représente fidèlement toutes les opinions","Il favorise les petits partis","Il supprime l’abstention"]'::jsonb, 0, 'Au prix d’une représentation moins fidèle.', 2),
    ('d04f44dd-6c49-5803-880f-f5815ecb64ef'::uuid, '8d1a293e-3257-5674-8f42-e139497cb150'::uuid, 'Quel est le principal avantage du scrutin proportionnel ?', 'mcq', '["Il représente fidèlement la diversité des opinions","Il garantit une majorité absolue","Il supprime les coalitions","Il renforce le lien avec la circonscription"]'::jsonb, 0, 'Au prix d’une majorité plus difficile à constituer.', 3),
    ('78effb37-df62-5c87-9d7f-20bebd610e2e'::uuid, '8d1a293e-3257-5674-8f42-e139497cb150'::uuid, 'Quelle élection française se déroule à la proportionnelle ?', 'mcq', '["L’élection des députés européens","L’élection présidentielle","Les élections législatives","L’élection des sénateurs"]'::jsonb, 0, 'Sur une circonscription nationale unique.', 4),
    ('d2950844-1394-5f61-8ced-93bbfa4b85bc'::uuid, '8d1a293e-3257-5674-8f42-e139497cb150'::uuid, 'Qu’est-ce qu’un seuil électoral ?', 'mcq', '["Le pourcentage minimal de voix requis pour obtenir des sièges","Le taux de participation minimal","Le nombre de signatures pour se présenter","Le plafond de dépenses de campagne"]'::jsonb, 0, 'Il écarte les très petites listes de la répartition.', 5),
    ('87bc95e9-49eb-5b1e-9161-3811e5e95eb6'::uuid, '8d1a293e-3257-5674-8f42-e139497cb150'::uuid, 'Le découpage des circonscriptions peut influencer le résultat d’une élection.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On parle de charcutage électoral quand il est manipulé.', 6),
    ('3be2f29b-d084-532f-87dc-c4362211654c'::uuid, '8d1a293e-3257-5674-8f42-e139497cb150'::uuid, 'Quel pays combine scrutin majoritaire et proportionnel pour son Parlement ?', 'mcq', '["L’Allemagne","Le Royaume-Uni","Les États-Unis","L’Espagne"]'::jsonb, 0, 'Un système mixte, dit proportionnel personnalisé.', 7),
    ('6254b0b0-9212-5bdd-ad08-f9c1b9601df3'::uuid, '8d1a293e-3257-5674-8f42-e139497cb150'::uuid, 'Le mode de scrutin est-il un choix technique neutre ?', 'mcq', '["Non, il oriente la composition de l’assemblée élue","Oui, il est purement administratif","Oui, s’il est appliqué correctement","Non, il est interdit d’en changer"]'::jsonb, 0, 'Les mêmes voix donnent des assemblées différentes.', 8),
    ('2f637b9c-764c-5591-9e5a-c50667a9ebb9'::uuid, '047e1ad5-2f22-5274-9a9d-eb4de360b62a'::uuid, 'Quelles sont les fonctions d’un parti politique ?', 'mcq', '["Sélectionner des candidats, élaborer un programme, mobiliser et structurer le débat","Gérer les services publics","Contrôler les élections","Rédiger les lois"]'::jsonb, 0, 'Il fait le lien entre la société et les institutions.', 1),
    ('8af2945d-f883-50ba-bba5-31681ba6fcd9'::uuid, '047e1ad5-2f22-5274-9a9d-eb4de360b62a'::uuid, 'Comment les partis sont-ils financés en France ?', 'mcq', '["En partie sur fonds publics, selon les résultats électoraux et la parité","Uniquement par les dons privés","Uniquement par les cotisations","Par les entreprises"]'::jsonb, 0, 'Leurs comptes sont contrôlés par une commission dédiée.', 2),
    ('0cf06f68-21d2-51b4-8881-f2659eb25e9b'::uuid, '047e1ad5-2f22-5274-9a9d-eb4de360b62a'::uuid, 'Qu’est-ce qu’un groupe d’intérêt ?', 'mcq', '["Une organisation qui défend des intérêts particuliers auprès des pouvoirs publics","Un parti politique","Un groupe parlementaire","Un institut de sondage"]'::jsonb, 0, 'Syndicats, patronat, ONG, associations d’usagers.', 3),
    ('75dc57cf-0676-535d-98ab-94e6783fa7a2'::uuid, '047e1ad5-2f22-5274-9a9d-eb4de360b62a'::uuid, 'Le lobbying est-il encadré en France ?', 'mcq', '["Oui, par un registre des représentants d’intérêts","Non, il est libre","Non, il est interdit","Oui, mais seulement au Parlement européen"]'::jsonb, 0, 'La transparence est la contrepartie de son autorisation.', 4),
    ('6adfc854-c6d9-5b78-8bf9-6437bf974513'::uuid, '047e1ad5-2f22-5274-9a9d-eb4de360b62a'::uuid, 'Quel risque les réseaux sociaux font-ils peser sur le débat public ?', 'mcq', '["La désinformation et l’enfermement dans des bulles de filtre","La disparition des partis","La fin des élections","L’interdiction des sondages"]'::jsonb, 0, 'Ils accélèrent aussi la circulation de l’information.', 5),
    ('d19c4614-6f9a-5226-ab20-8b77ac594463'::uuid, '047e1ad5-2f22-5274-9a9d-eb4de360b62a'::uuid, 'L’abstention est un comportement politique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle peut exprimer de l’indifférence comme une protestation.', 6),
    ('b1ae584e-09c4-5933-9919-c0dd3b0d4f3a'::uuid, '047e1ad5-2f22-5274-9a9d-eb4de360b62a'::uuid, 'Quelles formes peut prendre la participation politique ?', 'mcq', '["Vote, militantisme, pétition, manifestation, boycott, engagement associatif","Le vote uniquement","Le vote et l’adhésion à un parti","La candidature à une élection"]'::jsonb, 0, 'Elle déborde largement le jour du scrutin.', 7),
    ('eec2e0bb-d12c-5d8f-8aac-a9cdaa162bc4'::uuid, '047e1ad5-2f22-5274-9a9d-eb4de360b62a'::uuid, 'Chez qui l’abstention progresse-t-elle le plus ?', 'mcq', '["Chez les jeunes et les moins diplômés","Chez les cadres","Chez les retraités","Chez les élus locaux"]'::jsonb, 0, 'Un enjeu majeur pour la représentativité des élus.', 8),
    ('3f7fc301-843d-536d-be6a-2882da90305f'::uuid, 'f5a904fc-8c20-5321-a3c0-de8af92e5993'::uuid, 'Qu’est-ce que le capital humain ?', 'mcq', '["L’ensemble des connaissances, compétences et de la santé qui rendent le travail productif","Le nombre de salariés","Le capital détenu par les ménages","La masse salariale d’une entreprise"]'::jsonb, 0, 'Notion formulée notamment par Gary Becker.', 1),
    ('f6772bf0-904a-5634-b441-495d3c65e949'::uuid, 'f5a904fc-8c20-5321-a3c0-de8af92e5993'::uuid, 'Quel économiste a formalisé la théorie du capital humain ?', 'mcq', '["Gary Becker","John Maynard Keynes","Adam Smith","Karl Marx"]'::jsonb, 0, 'Il applique le raisonnement de l’investissement à la formation.', 2),
    ('ef1f5c9c-7c72-5025-a432-3b170be87eec'::uuid, 'f5a904fc-8c20-5321-a3c0-de8af92e5993'::uuid, 'Quel est le coût d’opportunité des études ?', 'mcq', '["Les revenus auxquels on renonce pendant la durée des études","Les frais de scolarité","Le prix des livres","Le coût du logement étudiant"]'::jsonb, 0, 'C’est un coût indirect, souvent le plus élevé.', 3),
    ('a7cef08f-150d-5fc9-a793-4c2a8c1a1742'::uuid, 'f5a904fc-8c20-5321-a3c0-de8af92e5993'::uuid, 'Quels avantages attend-on d’un investissement en formation ?', 'mcq', '["Un salaire plus élevé et un risque de chômage plus faible","Une réduction d’impôt","Un accès à la fonction publique","Une retraite anticipée"]'::jsonb, 0, 'Ainsi que de meilleures conditions et perspectives de carrière.', 4),
    ('b8cbe859-7af1-5943-ae30-311256f6a765'::uuid, 'f5a904fc-8c20-5321-a3c0-de8af92e5993'::uuid, 'Qu’est-ce que le déclassement ?', 'mcq', '["Occuper un emploi moins qualifié que son diplôme","Perdre son emploi","Changer de secteur d’activité","Être rétrogradé après une faute"]'::jsonb, 0, 'Il concerne particulièrement les jeunes diplômés en début de carrière.', 5),
    ('f886cf0a-a317-58a4-902d-eec43fd5ea31'::uuid, 'f5a904fc-8c20-5321-a3c0-de8af92e5993'::uuid, 'Selon la théorie du signal, le diplôme informe l’employeur sur des qualités difficiles à observer.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Persévérance, capacité d’apprentissage, aptitude à suivre des règles.', 6),
    ('5a319446-6cd2-5366-80d1-2d5058b99f66'::uuid, 'f5a904fc-8c20-5321-a3c0-de8af92e5993'::uuid, 'La qualification se confond-elle avec le poste occupé ?', 'mcq', '["Non, on peut occuper un poste moins qualifié que sa qualification","Oui, toujours","Oui, dans le secteur privé","Non, elle ne dépend que de l’ancienneté"]'::jsonb, 0, 'D’où la notion de déclassement.', 7),
    ('51a69d39-ae86-5791-a861-2c06fe0f7723'::uuid, 'f5a904fc-8c20-5321-a3c0-de8af92e5993'::uuid, 'Comment accumule-t-on du capital humain ?', 'mcq', '["Par la formation initiale, l’expérience et la formation continue","Par l’épargne","Par l’héritage uniquement","Par l’achat d’équipements"]'::jsonb, 0, 'L’expérience compte autant que le diplôme dans certains métiers.', 8),
    ('c358ac97-d66e-5e9e-a40e-46cf4a635534'::uuid, 'e0d3dc90-2333-5473-8c92-55181dee264e'::uuid, 'Qui est chômeur au sens du Bureau international du travail ?', 'mcq', '["Une personne sans emploi, disponible et en recherche active","Toute personne inscrite à France Travail","Toute personne sans revenu","Toute personne en formation"]'::jsonb, 0, 'Trois conditions cumulatives.', 1),
    ('1d714db4-6519-5a14-a57c-288228fd5442'::uuid, 'e0d3dc90-2333-5473-8c92-55181dee264e'::uuid, 'Comment calcule-t-on le taux de chômage ?', 'mcq', '["Chômeurs rapportés à la population active","Chômeurs rapportés à la population totale","Chômeurs rapportés aux actifs occupés","Chômeurs rapportés aux salariés"]'::jsonb, 0, 'La population active comprend les actifs occupés et les chômeurs.', 2),
    ('76da7469-4a85-54a3-a490-71dd96136875'::uuid, 'e0d3dc90-2333-5473-8c92-55181dee264e'::uuid, 'Quel type de chômage résulte d’une inadéquation des qualifications ?', 'mcq', '["Le chômage structurel","Le chômage conjoncturel","Le chômage frictionnel","Le chômage saisonnier"]'::jsonb, 0, 'Il ne se résorbe pas par la seule reprise économique.', 3),
    ('7e612937-a6ce-5cf2-88d4-1eeb59125c0a'::uuid, 'e0d3dc90-2333-5473-8c92-55181dee264e'::uuid, 'Quels emplois l’automatisation détruit-elle le plus ?', 'mcq', '["Les emplois routiniers peu qualifiés","Les emplois de cadres","Les emplois de santé","Les emplois artistiques"]'::jsonb, 0, 'Elle en crée d’autres, plus qualifiés.', 4),
    ('9d038167-4520-54f3-841d-e5fef2f2c0df'::uuid, 'e0d3dc90-2333-5473-8c92-55181dee264e'::uuid, 'Qu’est-ce que le chômage frictionnel ?', 'mcq', '["Le chômage lié au temps de recherche entre deux emplois","Le chômage dû à une crise","Le chômage de longue durée","Le chômage des seniors"]'::jsonb, 0, 'Il existe même quand l’économie va bien.', 5),
    ('b04e4e98-494d-5e33-921e-06406ccb1ed9'::uuid, 'e0d3dc90-2333-5473-8c92-55181dee264e'::uuid, 'Le taux de chômage des non-diplômés est plus élevé que celui des diplômés du supérieur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’écart est de plusieurs points, durablement.', 6),
    ('c15895a0-14a7-5ee5-b633-355bcc9b65f8'::uuid, 'e0d3dc90-2333-5473-8c92-55181dee264e'::uuid, 'Quelle politique vise le chômage structurel lié aux qualifications ?', 'mcq', '["La formation et l’apprentissage","La relance de la demande","La baisse des taux d’intérêt","L’augmentation des dépenses publiques"]'::jsonb, 0, 'Soutenir la demande traite le chômage conjoncturel, pas celui-là.', 7),
    ('8ab12578-a717-5056-9890-9b637517faae'::uuid, 'e0d3dc90-2333-5473-8c92-55181dee264e'::uuid, 'Pourquoi allège-t-on les cotisations sur les bas salaires ?', 'mcq', '["Pour réduire le coût du travail des emplois les moins productifs","Pour augmenter les salaires nets","Pour financer la formation","Pour favoriser les exportations"]'::jsonb, 0, 'Une politique très utilisée en France depuis les années 1990.', 8),
    ('f7e74e89-fe94-57ee-a060-0c5606936da0'::uuid, '53f408e3-7afd-5bdc-a7a2-600799206b46'::uuid, 'Quelle relation observe-t-on entre diplôme et salaire ?', 'mcq', '["Le salaire moyen augmente avec le niveau de diplôme","Le salaire est indépendant du diplôme","Le salaire baisse avec le diplôme","La relation n’existe qu’en début de carrière"]'::jsonb, 0, 'Et l’écart se creuse au fil de la carrière.', 1),
    ('00fbc451-3811-539c-a208-71008aaeb81c'::uuid, '53f408e3-7afd-5bdc-a7a2-600799206b46'::uuid, 'Quelle différence entre expérience et ancienneté ?', 'mcq', '["L’expérience accroît la productivité, l’ancienneté est souvent rémunérée par convention","Ce sont deux synonymes","L’ancienneté est illégale","L’expérience ne compte pas dans le salaire"]'::jsonb, 0, 'Les grilles conventionnelles rémunèrent l’ancienneté.', 2),
    ('475f0bbc-f21d-51eb-b13d-9f01a3d9830e'::uuid, '53f408e3-7afd-5bdc-a7a2-600799206b46'::uuid, 'Comment évolue la courbe des salaires au cours d’une carrière ?', 'mcq', '["Forte progression au début, puis aplatissement","Progression linéaire jusqu’à la retraite","Baisse continue","Aucune évolution"]'::jsonb, 0, 'Effet plus marqué pour les cadres que pour les ouvriers.', 3),
    ('cced97f8-5fcf-51ca-a854-e662ff2893d3'::uuid, '53f408e3-7afd-5bdc-a7a2-600799206b46'::uuid, 'Qu’est-ce qu’une convention collective ?', 'mcq', '["Un accord de branche fixant notamment des grilles de salaires","Un contrat de travail individuel","Une loi votée par le Parlement","Un règlement intérieur d’entreprise"]'::jsonb, 0, 'Elle s’impose aux entreprises de la branche.', 4),
    ('56d5c4b1-e90c-585d-9f0e-cabe8959efa3'::uuid, '53f408e3-7afd-5bdc-a7a2-600799206b46'::uuid, 'Le salaire minimum fixe un plancher légal de rémunération.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Aucune rémunération ne peut lui être inférieure pour un temps plein.', 5),
    ('5533ccdd-95f5-5e22-9d0e-ba6bf4f644ca'::uuid, '53f408e3-7afd-5bdc-a7a2-600799206b46'::uuid, 'Les grandes entreprises paient-elles en moyenne davantage ?', 'mcq', '["Oui, à qualification comparable","Non, moins","Elles paient exactement pareil","Cela dépend uniquement de la région"]'::jsonb, 0, 'Effet de taille bien documenté.', 6),
    ('91f097ce-b55c-5111-b11e-561485210949'::uuid, '53f408e3-7afd-5bdc-a7a2-600799206b46'::uuid, 'Qu’est-ce qui, en dehors du diplôme, influence le salaire ?', 'mcq', '["Le secteur, la taille de l’entreprise, la région et le pouvoir de négociation","Uniquement l’âge","Uniquement le statut marital","Uniquement la durée du contrat"]'::jsonb, 0, 'Le salaire résulte aussi d’un rapport de force.', 7),
    ('67335831-24f8-52ae-b77c-2d4d8eaccf7b'::uuid, '53f408e3-7afd-5bdc-a7a2-600799206b46'::uuid, 'La loi impose-t-elle l’égalité salariale entre femmes et hommes ?', 'mcq', '["Oui, pour un même travail ou un travail de valeur égale","Non, elle recommande seulement","Oui, depuis 2020 uniquement","Non, cela relève des entreprises"]'::jsonb, 0, 'L’écart persiste malgré la règle.', 8),
    ('52a2896f-cfbc-5b90-96fe-2ac497b55ded'::uuid, '3f004ee3-f77e-50e5-8b1a-313eddff8f1e'::uuid, 'Quel est approximativement l’écart de salaire entre femmes et hommes en équivalent temps plein en France ?', 'mcq', '["Environ 14 %","Environ 40 %","Environ 2 %","Il n’y a plus d’écart"]'::jsonb, 0, 'Il se réduit à environ 4 % à poste et profil comparables.', 1),
    ('a7b334a3-f912-52c9-9262-3cdb2ea95bf5'::uuid, '3f004ee3-f77e-50e5-8b1a-313eddff8f1e'::uuid, 'Quel mécanisme explique une partie de l’écart salarial entre femmes et hommes ?', 'mcq', '["Le temps partiel, très féminin","Un niveau de diplôme inférieur des femmes","Une productivité moindre","Une législation défavorable"]'::jsonb, 0, 'Avec la ségrégation professionnelle et les interruptions de carrière.', 2),
    ('61ac2200-da9b-5636-899c-d37090981356'::uuid, '3f004ee3-f77e-50e5-8b1a-313eddff8f1e'::uuid, 'Qu’est-ce que le plafond de verre ?', 'mcq', '["Un obstacle invisible qui limite l’accès des femmes aux postes de direction","Une limite légale de salaire","Un seuil d’imposition","Un plafond de cotisations"]'::jsonb, 0, 'Il ne figure dans aucun règlement mais produit des effets mesurables.', 3),
    ('b0111c48-1b7b-5dd2-8f45-098f68ddef49'::uuid, '3f004ee3-f77e-50e5-8b1a-313eddff8f1e'::uuid, 'Qu’est-ce que la ségrégation professionnelle ?', 'mcq', '["La concentration des femmes et des hommes dans des métiers différents","L’interdiction d’exercer certains métiers","La séparation des équipes dans l’entreprise","Le refus d’embaucher des jeunes"]'::jsonb, 0, 'Les métiers très féminisés sont en moyenne moins rémunérés.', 4),
    ('bba8245b-6d83-5ba2-8e6c-48231e430442'::uuid, '3f004ee3-f77e-50e5-8b1a-313eddff8f1e'::uuid, 'Pourquoi, à diplôme égal, les enfants de cadres réussissent-ils mieux professionnellement ?', 'mcq', '["Réseaux, information, codes sociaux et soutien financier","Un diplôme de meilleure qualité","Une intelligence supérieure","Un droit d’accès prioritaire"]'::jsonb, 0, 'Des ressources qui ne figurent sur aucun CV.', 5),
    ('7567f22d-eb9a-5a5e-bb60-bf0e583783a7'::uuid, '3f004ee3-f77e-50e5-8b1a-313eddff8f1e'::uuid, 'La mobilité sociale a totalement disparu en France.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle existe, mais la reproduction reste forte aux deux extrémités.', 6),
    ('f8553fe8-53c9-5384-8a2e-186782690047'::uuid, '3f004ee3-f77e-50e5-8b1a-313eddff8f1e'::uuid, 'Comment mesure-t-on les discriminations à l’embauche ?', 'mcq', '["Par des tests envoyant des candidatures comparables ne différant que par un critère","Par des sondages d’opinion","Par les déclarations des entreprises","Elles ne sont pas mesurables"]'::jsonb, 0, 'La méthode du testing isole l’effet du critère discriminant.', 7),
    ('2dfc9514-13f6-5dee-bbeb-70cde18fee14'::uuid, '3f004ee3-f77e-50e5-8b1a-313eddff8f1e'::uuid, 'Quelle mesure vise à féminiser les instances dirigeantes ?', 'mcq', '["Les lois sur la parité dans les conseils d’administration","Le salaire minimum","Les allègements de cotisations","Le compte personnel de formation"]'::jsonb, 0, 'Avec l’index d’égalité professionnelle.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('ses');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('ses')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 280 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 280 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
